package com.dm.travel_planner.domain.ledger.investment.service;

import com.dm.travel_planner.domain.ledger.entity.*;
import com.dm.travel_planner.domain.ledger.entity.Currency;
import com.dm.travel_planner.domain.ledger.repository.AccountRepository;
import com.dm.travel_planner.domain.ledger.investment.entity.*;
import com.dm.travel_planner.domain.ledger.investment.repository.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.*;
import org.mockito.junit.jupiter.MockitoExtension;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import static org.mockito.Mockito.*;
import static org.assertj.core.api.Assertions.*;

@ExtendWith(MockitoExtension.class)
class InvestmentTaxEstimateServiceTest {
    @Mock AccountRepository accounts; @Mock InvestmentRepository holdings; @Mock InvestmentTransactionRepository transactions;
    @Mock InvestmentTaxRecordRepository records; @Mock TaxResidenceService residences;
    InvestmentTaxEstimateService service;
    Account account; Investment holding; List<InvestmentTransaction> trades;
    BigDecimal n(String s){return new BigDecimal(s);}
    @BeforeEach void setup(){service=new InvestmentTaxEstimateService(accounts,holdings,transactions,records,residences,new ObjectMapper());account=account("a",Currency.KRW,"KR",InvestmentTaxAccountType.GENERAL);holding=Investment.builder().investmentId("h").accountId("a").assetClass(InvestmentAssetClass.DOMESTIC_STOCK).market("KRX").build();trades=new ArrayList<>();}
    Account account(String id,Currency currency,String country,InvestmentTaxAccountType type){return Account.builder().accountId(id).accountName(id).accountType(AccountType.INVESTMENT).currency(currency).brokerageCountry(country).brokerageTaxType(type).build();}
    TaxResidence residence(String c,LocalDate from){var r=new TaxResidence();r.setCountry(c);r.setEffectiveFrom(from);return r;}
    InvestmentTransaction sale(String id,String gain,String tax,InvestmentTaxKind kind){return InvestmentTransaction.builder().investmentTransactionId(id).investmentId("h").tradeType(InvestmentTradeType.SELL).tradeDate(LocalDateTime.of(2026,3,1,12,0)).realizedProfitLoss(n(gain)).taxAmount(n(tax)).taxKind(kind).currency(Currency.KRW).exchangeRate(BigDecimal.ONE).build();}
    void data(String res){when(accounts.findByUserIdOrderByDisplayOrderAsc("u")).thenReturn(List.of(account));when(holdings.findByAccountIdAndUserId("a","u")).thenReturn(List.of(holding));when(transactions.findByInvestmentIdOrderByCreatedAtAscInvestmentTransactionIdAsc("h")).thenAnswer(i->trades);when(residences.list("u")).thenReturn(List.of(residence(res,LocalDate.of(2026,1,1))));}
    @Test void koreanTransactionTaxIsExpenseNotJapaneseTaxCredit(){data("JP");trades.add(sale("s","1000000","1000",InvestmentTaxKind.TRANSACTION_TAX));var r=service.report("u",2026,Map.of("KRW_JPY",n("0.1")));assertThat(r.totals().getFirst().estimatedTax()).isEqualByComparingTo("20315");assertThat(r.totals().getFirst().withheld()).isZero();assertThat(r.transactionTaxes().get(Currency.KRW)).isEqualByComparingTo("1000");assertThat(r.issues()).isEmpty();verify(accounts,never()).save(any());}
    @Test void lossesOffsetProfitsBeforeApplyingAnnualRate(){data("JP");trades.add(sale("s1","1000000","0",InvestmentTaxKind.TRANSACTION_TAX));trades.add(sale("s2","-400000","0",InvestmentTaxKind.TRANSACTION_TAX));assertThat(service.report("u",2026,Map.of("KRW_JPY",n("0.1"))).totals().getFirst().estimatedTax()).isEqualByComparingTo("12189");}
    @Test void missingFxNeverBecomesZeroTax(){data("JP");trades.add(sale("s","1000","0",InvestmentTaxKind.TRANSACTION_TAX));var r=service.report("u",2026,Map.of());assertThat(r.requiredRates()).containsExactly("KRW_JPY");assertThat(r.totals().getFirst().estimatedTax()).isNull();assertThat(r.issues()).isNotEmpty();}
    @Test void nisaLossIsExcludedFromTaxableJapaneseGains(){data("JP");trades.add(sale("taxable","1000000","0",InvestmentTaxKind.TRANSACTION_TAX));var nisa=InvestmentTransaction.builder().investmentTransactionId("nisa").investmentId("h").tradeType(InvestmentTradeType.SELL).tradeDate(LocalDateTime.of(2026,5,1,0,0)).realizedProfitLoss(n("-1000000")).taxResidence("JP").taxAccountCountry("JP").taxAccountType(InvestmentTaxAccountType.NISA).taxTreatment(InvestmentTaxTreatment.NISA).build();trades.add(nisa);assertThat(service.report("u",2026,Map.of("KRW_JPY",n("0.1"))).totals().getFirst().estimatedTax()).isEqualByComparingTo("20315");}
    @Test void incomeWithholdingIsAddedBackAndCreditedOnlyOnce(){account=account("a",Currency.JPY,"JP",InvestmentTaxAccountType.SPECIFIC_WITHHOLDING);data("JP");trades.add(sale("s","80000","20000",InvestmentTaxKind.WITHHOLDING_TAX));var r=service.report("u",2026,Map.of());assertThat(r.totals().getFirst().realizedProfit()).isEqualByComparingTo("100000");assertThat(r.totals().getFirst().estimatedTax()).isEqualByComparingTo("20315");assertThat(r.totals().getFirst().withheld()).isEqualByComparingTo("20000");}
    @Test void domesticKoreanGeneralStockDoesNotGetForeignCapitalGainsRate(){data("KR");trades.add(sale("s","10000000","1000",InvestmentTaxKind.TRANSACTION_TAX));assertThat(service.report("u",2026,Map.of()).totals().getFirst().estimatedTax()).isZero();}
    @Test void koreanForeignDeductionIsAppliedOnceAcrossAccounts(){data("KR");account=account("a",Currency.KRW,"JP",InvestmentTaxAccountType.GENERAL);var other=account("b",Currency.KRW,"JP",InvestmentTaxAccountType.GENERAL);when(accounts.findByUserIdOrderByDisplayOrderAsc("u")).thenReturn(List.of(account,other));var h2=Investment.builder().investmentId("h2").market("TSE").assetClass(InvestmentAssetClass.FOREIGN_STOCK).build();holding=Investment.builder().investmentId("h").market("TSE").assetClass(InvestmentAssetClass.FOREIGN_STOCK).build();when(holdings.findByAccountIdAndUserId("a","u")).thenReturn(List.of(holding));when(holdings.findByAccountIdAndUserId("b","u")).thenReturn(List.of(h2));trades.add(sale("s","3000000","0",InvestmentTaxKind.TRANSACTION_TAX));when(transactions.findByInvestmentIdOrderByCreatedAtAscInvestmentTransactionIdAsc("h2")).thenReturn(List.of(sale("s2","3000000","0",InvestmentTaxKind.TRANSACTION_TAX)));assertThat(service.report("u",2026,Map.of()).totals().getFirst().estimatedTax()).isEqualByComparingTo("770000");}
    @Test void savedTradeResidenceSurvivesLaterResidenceChanges(){data("KR");trades.add(InvestmentTransaction.builder().investmentTransactionId("s").investmentId("h").tradeType(InvestmentTradeType.SELL).tradeDate(LocalDateTime.of(2026,3,1,0,0)).taxResidence("JP").taxAccountCountry("KR").taxAccountType(InvestmentTaxAccountType.GENERAL).taxTreatment(InvestmentTaxTreatment.ANNUAL).realizedProfitLoss(n("1000")).build());var r=service.report("u",2026,Map.of("KRW_JPY",n("0.1")));assertThat(r.totals().getFirst().country()).isEqualTo("JP");}
    @Test void oldUnclassifiedTaxBlocksMisleadingEstimate(){data("JP");trades.add(sale("s","1000","10",InvestmentTaxKind.UNCLASSIFIED));var r=service.report("u",2026,Map.of("KRW_JPY",n("0.1")));assertThat(r.totals().getFirst().estimatedTax()).isNull();assertThat(r.unclassifiedTaxes().get(Currency.KRW)).isEqualByComparingTo("10");}
    @Test void completionKeepsSnapshotAndDetectsLaterTradeChanges(){data("JP");trades.add(sale("s","1000000","0",InvestmentTaxKind.TRANSACTION_TAX));var row=new InvestmentTaxRecord();row.setId("u:2026:year");row.setUserId("u");row.setTaxYear(2026);when(records.findById("u:2026:year")).thenReturn(Optional.of(row));when(records.saveAndFlush(any())).thenAnswer(i->{row.setVersion(row.getVersion()==null?0:row.getVersion()+1);return row;});service.calculate("u",2026,new InvestmentTaxEstimateService.Calculate(Map.of("KRW_JPY",n("0.1")),null));String snapshot=row.getEstimateSnapshot();service.settle("u",2026,new InvestmentTaxEstimateService.Settle("COMPLETE",Map.of("JPY",n("20000")),LocalDate.of(2026,3,1),0L));assertThat(row.getCompletedAt()).isNotNull();trades.add(sale("later","500000","0",InvestmentTaxKind.TRANSACTION_TAX));var view=service.overview("u",2026);assertThat(view.changed()).isTrue();assertThat(row.getEstimateSnapshot()).isEqualTo(snapshot);assertThat(view.payments().get("JPY")).isEqualByComparingTo("20000");assertThatThrownBy(()->service.calculate("u",2026,new InvestmentTaxEstimateService.Calculate(Map.of(),1L))).hasMessageContaining("정산 수정");}
    @Test void staleOrIncompleteEstimateCannotBeMarkedComplete(){data("JP");trades.add(sale("s","1000","0",InvestmentTaxKind.TRANSACTION_TAX));var row=new InvestmentTaxRecord();when(records.findById("u:2026:year")).thenReturn(Optional.of(row));when(records.saveAndFlush(any())).thenAnswer(i->row);service.calculate("u",2026,new InvestmentTaxEstimateService.Calculate(Map.of(),null));assertThatThrownBy(()->service.settle("u",2026,new InvestmentTaxEstimateService.Settle("COMPLETE",Map.of("JPY",BigDecimal.ZERO),LocalDate.of(2026,3,1),null))).hasMessageContaining("자료 부족");}
    @Test void anotherUsersAccountCannotBeUsedForTradeContext(){when(accounts.findByAccountIdAndUserId("a","other")).thenReturn(Optional.empty());assertThatThrownBy(()->service.context("other","a",LocalDate.now())).hasMessageContaining("404");}
}
